INSERT INTO `catalog_pages` VALUES (302, 209, 'asian', 'Aziatisch', 'default_3x3', 1, 15, 1, 1, '1', '1', '0', '0', 'catalog_asian_headline1', 'catalog_asian_teaser1', '', 'Ting tong! Ching chong? Ting chong ting, ping ping! I mean uh.. with our authentic Chinese furniture, you can make a beautiful oriental room!', '', '', '', 0, '');
