INSERT INTO `catalog_pages` VALUES (72, 209, 'pirates', 'Piraten', 'default_3x3', 1, 190, 1, 17, '1', '1', '0', '0', 'catalog_header_pirate', 'pirate_bundle', '', 'Yarrr! Harrrrr! Fiddle dee dee, being a pirate is alright with me!', '', '', '', 0, '');
