INSERT INTO `catalog_pages` VALUES (116, 209, 'attic', 'Zolder', 'default_3x3', 1, 242, 1, 1, '1', '1', '0', '0', 'attic15_catalog_header', 'attic15_catalog_teaser', '', 'From idueaky floor boards to ancient furniture, the Attic 2015 furniture is now here!', '', '', '', 0, '');
