INSERT INTO `catalog_pages` VALUES (224, 568, '9', 'Teleportaties', 'default_3x3', 1, 120, 1, 9, '1', '1', '0', '0', 'catalog_doors_headline1', 'catalog_door_a', '', 'Beam yourself from one room to another with our space-age teleports. Buy a pair, put one in each room and you\'ve got your own suite! IMPORTANT: teleports are always sold in pairs except for the Random Banzai Teleport.', '', NULL, 'Click on an item for details.', 0, '');
INSERT INTO `catalog_pages` VALUES (225, 2, '', 'Trofeeën', 'trophies', 1, 221, 1, 12, '1', '1', '0', '0', 'trophies', '', '', 'Everyone\'s a winner, baby! Reward them all with fabulous glittering array of bronze, silver and gold trophies. First choose the trophy model by clicking the arrows. Then select the style. Type your message below and we\'ll engrave it on the trophy along with your name and today\'s date. Remember - it\'s permanent!', '', '', '', 0, '');
