INSERT INTO `catalog_pages` VALUES (83, 277, 'spider', 'Spinnen', 'pets', 1, 95, 1, 13, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'One of the most feared creatures in nature, and perhaps the most misunderstood. The majority of Spiders have sharp fangs that inject venom into their prey- but don\'t worry, these spiders won\'t bite! Maybe...', '', 'Name your pet:', '', 0, '');
INSERT INTO `catalog_pages` VALUES (82, 277, 'rhino', 'Neushoorns', 'pets', 1, 77, 1, 12, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'The Rhinoceros is an African herbivore that can weigh over a ton. It is proud and slightly aloof, but loyal and never let anything get in the way of a good time!', 'Name your pet:', 'Choose a colour:', 'Choose a breed:', 0, '');
