INSERT INTO `catalog_pages` VALUES (46, 253, 'trax', 'Muziek', 'default_3x3', 1, 4, 1, 2, '1', '1', '0', '0', 'music_header', 'hotelhits_teaser', '', 'Trax are the Habbo music disks which have many multiple tunes installed onto them which can be played on a Trax Machine in the room. After the Habbo transistion from Shockwave to Flash clients, the trax system was not recovered until April 2011, where only Juke Boxes, old CDs, and Habbo sold CDs were re-released.', '', 'For decoration only.. They do not function.', '', 0, '');
